function wordImageUrl(word) {
  const p = WORD_IMAGES[word];
  if (!p) return null;
  if (p.startsWith('http')) return p;
  return 'https://thumb.wikimedia.org/wikipedia/commons/thumb/' + p + '/250px-' + p.slice(p.lastIndexOf('/') + 1);
}
